mapper.select:
SELECT COUNT(*) FROM sa_conversation
WHERE user_id = #{userId} AND project_id = #{projectId}
AND title LIKE CONCAT('%', #{keyword}, '%')
AND mode = #{mode}

SELECT c.id, c.user_id, c.project_id, c.knowledge_snapshot_id, c.knowledge_base_id, c.title, c.mode, c.create_time, c.update_time,
       (SELECT COUNT(*) FROM sa_message m WHERE m.conversation_id = c.id AND m.user_id = c.user_id) AS message_count
FROM sa_conversation c
WHERE c.user_id = #{userId} AND c.project_id = #{projectId}
AND c.title LIKE CONCAT('%', #{keyword}, '%')
AND c.mode = #{mode}
ORDER BY c.update_time DESC, c.id DESC
LIMIT #{offset}, #{pageSize}
